// Package adt is the Gom abstract-syntax-tree package, generated by the
// Go Gom itself (tom/gom/backend) from the five .gom files in
// src/tom/gom/adt/:
//
//	Code.gom  Gom.gom  Objects.gom  Rule.gom  SymbolTable.gom
//
// This is the self-bootstrap of the Gom AST: the Go Gom parser and
// backend manipulate exactly the same abstract structures the reference
// Java Gom does. Importers conventionally alias it as gomast:
//
//	import gomast "tom/gom/adt"
//
// Every term lives in the shared-objects factory of this package; two
// structurally equal terms compare equal by pointer.
//
// # Regeneration
//
// From the src/go/tom/ directory:
//
//	go run ./gom/cmd/gomgo gom-batch --pkg adt -o /tmp/adt \
//	    ../../tom/gom/adt/Code.gom \
//	    ../../tom/gom/adt/Gom.gom \
//	    ../../tom/gom/adt/Objects.gom \
//	    ../../tom/gom/adt/Rule.gom \
//	    ../../tom/gom/adt/SymbolTable.gom
//	cp /tmp/adt/*.go gom/adt/   # not go.mod: adt lives inside module tom
//	go test ./...
//
// TestSelfBootstrap (tom/gom/backend) checks that the committed sources
// are byte-identical to a fresh regeneration. The generated sources
// should NEVER be edited by hand — every change must go through the
// .gom sources and a clean regeneration.
package adt
